"""Per-tick bird physics. See spec/02_physics.md for the normative order."""

from units import G, FLAP_V, VY_MAX, FIELD_H, BIRD_H


def step_bird(y, vy, flap):
    """Advance the bird one tick; return (y, vy, alive)."""
    if flap:
        vy = FLAP_V
    else:
        vy = min(vy + G, VY_MAX)
    y += vy
    alive = True
    if y < 0:
        y = 0
        vy = 0
    elif y + BIRD_H > FIELD_H:
        y = FIELD_H - BIRD_H
        alive = False
    return (y, vy, alive)

"""Pipe generation and motion. See spec/03_world.md."""

from units import SPAWN_X, SCROLL, PIPE_W


def lcg(s):
    """One step of the linear congruential generator."""
    return (1103515245 * s + 12345) % 2147483648


def spawn(t, s):
    """On a spawn tick return (pipe, new_state); else (None, s)."""
    if t % SPAWN_EVERY != 0:
        return None, s
    s = lcg(s)
    pipe = {"x": SPAWN_X, "gap_top": 40 + (s >> 8) % 80, "passed": False}
    return pipe, s


def scroll(pipes):
    """Move every pipe left by SCROLL, in place."""
    for p in pipes:
        p["x"] -= SCROLL


def cull(pipes):
    """Drop pipes fully off the left edge; return the survivors."""
    return [p for p in pipes if p["x"] + PIPE_W > 0]

"""Simulation loop implementing the normative per-tick order (spec/02)."""

from units import BIRD_X, PIPE_W, GLIDE_VY
from physics import step_bird
from world import spawn, scroll, cull
from collide import pipe_hit


def run(seed, ticks, flaps, powerups=False, trace=None):
    y, vy, score = 560, 0, 0
    alive, s, pipes = True, seed, []
    shields, passed_n = (1, 0) if powerups else (0, 0)
    every = max(1, ticks // 20)
    ticks_run = 0
    for t in range(ticks):
        pipe, s = spawn(t, s)
        if pipe is not None:
            pipes.append(pipe)
        flap = bool(flaps) and flaps[t % len(flaps)] == "1"
        y, vy, alive = step_bird(y, vy, flap)
        scroll(pipes)
        if alive:
            for p in pipes:
                if pipe_hit(y, p):
                    if powerups and shields > 0:
                        shields -= 1
                        p["passed"] = True
                    else:
                        alive = False
                    break
            if alive:
                for p in pipes:
                    if not p["passed"] and p["x"] + PIPE_W <= BIRD_X:
                        p["passed"] = True
                        score += 1
                        if abs(vy) <= GLIDE_VY:
                            score += 1
                        if powerups:
                            passed_n += 1
                            if passed_n % 5 == 0:
                                shields = min(shields + 1, 3)
        pipes = cull(pipes)
        ticks_run = t + 1
        if trace is not None and t % every == 0:
            trace(t, y, vy, score, alive)
        if not alive:
            break
    state = {"y": y, "vy": vy, "score": score, "alive": alive,
